'use client';

import { useState, useRef, useEffect } from 'react';
import { Card } from '@/components/layout/Card';
import { Collapse } from '@/components/layout/Collapse';
import { ChevronDown, ChevronUp, Clock, FileText, Mic2, Music2, Lightbulb, CheckCircle2, Circle, Disc3, Play, Pause } from 'lucide-react';
import { useMusic } from '@/contexts/MusicContext';
import type { AlbumData, TrackStatus } from '@/types/album';

const ALBUM_COVER_ART = "data:image/png;base64,";


// ─── Data (from content/album.json) ─────────────────────────────────

const ALBUM_STATUS_TEXT = 'In progress' as const;
const ALBUM_STATUS_COLOR = 'bg-amber-500/20 text-amber-400';
const ALBUM_COVER_COLOR = 'from-amber-500/30 via-orange-500/20 to-rose-500/30';

interface AlbumViewModel {
  title: string;
  artist: string;
  year: string;
  status: typeof ALBUM_STATUS_TEXT;
  statusColor: string;
  concept: string;
  coverColor: string;
}

interface Track {
  number: string;
  title: string;
  status: TrackStatus;
  story?: string;
  notes?: string;
  tags?: string[];
  currentlyWorking?: boolean;
  demo?: string;
  lyrics?: string;
}

interface TimelineItem {
  date: string;
  event: string;
  detail?: string;
  done?: boolean;
}

interface LogEntry {
  date: string;
  content: string;
}

const trackStatusMap: Record<string, TrackStatus> = {
  Idea: 'Idea',
  Demo: 'Demo',
  Recording: 'Recording',
  Mixing: 'Mixing',
  Done: 'Done',
  idea: 'Idea',
  demo: 'Demo',
  recording: 'Recording',
  mixing: 'Mixing',
  done: 'Done',
};

const normalizeTrackStatus = (status?: string): TrackStatus => {
  if (!status) return 'Idea';
  const normalized = status.trim();
  return trackStatusMap[normalized] ?? trackStatusMap[normalized.toLowerCase()] ?? 'Idea';
};

const mapAlbumDataToView = (albumData: AlbumData): { album: AlbumViewModel; tracks: Track[] } => {
  const album: AlbumViewModel = {
    title: albumData.title,
    artist: albumData.artist,
    year: albumData.year,
    status: ALBUM_STATUS_TEXT,
    statusColor: ALBUM_STATUS_COLOR,
    concept: albumData.concept,
    coverColor: ALBUM_COVER_COLOR,
  };

  const tracks: Track[] = albumData.tracks.map((track, index) => ({
    number: track.number || String(index + 1).padStart(2, '0'),
    title: track.title || `Track ${String(index + 1).padStart(2, '0')}`,
    status: normalizeTrackStatus(track.status),
    story: track.story,
    notes: track.notes,
    tags: track.tags,
    currentlyWorking: track.currentlyWorking,
    demo: track.demo,
    lyrics: track.lyrics,
  }));

  return { album, tracks };
};

const timeline: TimelineItem[] = [];

const log: LogEntry[] = [];

// ─── Status config ──────────────────────────────────────────────────────

const statusConfig: Record<TrackStatus, { label: string; color: string; dot: string }> = {
  Idea:      { label: 'Idea',      color: 'bg-zinc-500/20 text-zinc-400',    dot: 'bg-zinc-500' },
  Demo:      { label: 'Demo',      color: 'bg-blue-500/20 text-blue-400',     dot: 'bg-blue-500' },
  Recording: { label: 'Recording', color: 'bg-purple-500/20 text-purple-400', dot: 'bg-purple-500' },
  Mixing:    { label: 'Mixing',    color: 'bg-orange-500/20 text-orange-400', dot: 'bg-orange-500' },
  Done:      { label: 'Done',      color: 'bg-emerald-500/20 text-emerald-400', dot: 'bg-emerald-500' },
};

// ─── Components ─────────────────────────────────────────────────────────

function DemoPlayer({ src, isDark, title }: { src: string; isDark: boolean; title: string }) {
  const audioRef    = useRef<HTMLAudioElement>(null);
  const progressRef = useRef<HTMLDivElement>(null);   // progress bar fill div
  const timeRef     = useRef<HTMLSpanElement>(null);  // time text span
  const rafRef      = useRef<number>(0);              // RAF ID
  const [playing,   setPlaying]   = useState(false);
  const [buffering, setBuffering] = useState(false);
  const { setMediaSessionDelegate } = useMusic();

  const fmt = (s: number) => {
    if (!s || !isFinite(s) || isNaN(s)) return '0:00';
    return `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;
  };

  // Single place to update the DOM
  const updateDOM = () => {
    const a = audioRef.current;
    if (!a) return;
    const ct = a.currentTime;
    const d  = a.duration;
    if (progressRef.current) {
      progressRef.current.style.width = `${d && isFinite(d) && d > 0 ? (ct / d) * 100 : 0}%`;
    }
    if (timeRef.current) {
      timeRef.current.textContent = `${fmt(ct)} / ${fmt(d)}`;
    }
  };

  // Driven by RAF
  const startTick = () => {
    cancelAnimationFrame(rafRef.current);
    const tick = () => {
      updateDOM();
      rafRef.current = requestAnimationFrame(tick);
    };
    rafRef.current = requestAnimationFrame(tick);
  };

  const stopTick = () => cancelAnimationFrame(rafRef.current);

  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;
    audio.preload = 'auto';
    audio.load();

    const onLoaded  = () => {
      setBuffering(false);
      if (timeRef.current) timeRef.current.textContent = `0:00 / ${fmt(audio.duration)}`;
    };
    const onWaiting = () => setBuffering(true);
    const onCanPlay = () => setBuffering(false);
    const onEnded   = () => {
      setPlaying(false);
      stopTick();
      if (progressRef.current) progressRef.current.style.width = '0%';
      if (timeRef.current)     timeRef.current.textContent = `0:00 / ${fmt(audio.duration)}`;
      audio.currentTime = 0;
      if ('mediaSession' in navigator) navigator.mediaSession.playbackState = 'paused';
      setMediaSessionDelegate(null);
    };
    
    // Belt and suspenders: driven by both RAF and timeupdate
    audio.addEventListener('timeupdate',     updateDOM);
    audio.addEventListener('loadedmetadata', onLoaded);
    audio.addEventListener('waiting',        onWaiting);
    audio.addEventListener('canplay',        onCanPlay);
    audio.addEventListener('ended',          onEnded);
    return () => {
      audio.removeEventListener('timeupdate',     updateDOM);
      audio.removeEventListener('loadedmetadata', onLoaded);
      audio.removeEventListener('waiting',        onWaiting);
      audio.removeEventListener('canplay',        onCanPlay);
      audio.removeEventListener('ended',          onEnded);
      cancelAnimationFrame(rafRef.current);
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Pause self when the main player or another demo starts
  useEffect(() => {
    const msOff = () => { if ('mediaSession' in navigator) navigator.mediaSession.playbackState = 'paused'; };
    const stopMain = () => { audioRef.current?.pause(); setPlaying(false); stopTick(); msOff(); setMediaSessionDelegate(null); };
    const stopDemo = (e: Event) => {
      if ((e as CustomEvent).detail?.src !== src) {
        audioRef.current?.pause();
        setPlaying(false);
        stopTick();
        msOff();
        setMediaSessionDelegate(null);
      }
    };
    window.addEventListener('main-play', stopMain);
    window.addEventListener('demo-play', stopDemo);
    return () => {
      window.removeEventListener('main-play', stopMain);
      window.removeEventListener('demo-play', stopDemo);
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [src]);

  const togglePlay = () => {
    const audio = audioRef.current;
    if (!audio || buffering) return;
    if (playing) {
      audio.pause();
      setPlaying(false);
      stopTick();
      setMediaSessionDelegate(null);
      if ('mediaSession' in navigator) navigator.mediaSession.playbackState = 'paused';
    } else {
      window.dispatchEvent(new CustomEvent('demo-play', { detail: { src } }));

      // Take over MediaSession play/pause/seekto routing via the delegate ref
      // Do not call setActionHandler directly, to avoid overriding handlers the main player registered at mount
      setMediaSessionDelegate({
        play: () => {
          audio.play().then(() => { setPlaying(true); startTick(); }).catch(() => {});
          if ('mediaSession' in navigator) navigator.mediaSession.playbackState = 'playing';
        },
        pause: () => {
          audio.pause(); setPlaying(false); stopTick();
          if ('mediaSession' in navigator) navigator.mediaSession.playbackState = 'paused';
        },
        seekto: (details) => {
          if (!audio || !audio.duration) return;
          if (details.fastSeek && !('fastSeek' in audio)) return;
          audio.currentTime = details.seekTime || 0;
          if (progressRef.current) progressRef.current.style.width = `${(audio.currentTime / audio.duration) * 100}%`;
          try {
            if (isFinite(audio.duration) && audio.duration > 0) {
              navigator.mediaSession.setPositionState({
                duration: audio.duration,
                playbackRate: audio.playbackRate,
                position: audio.currentTime,
              });
            }
          } catch (_) {}
        },
      });

      if ('mediaSession' in navigator) {
        navigator.mediaSession.playbackState = 'playing';
        navigator.mediaSession.metadata = new MediaMetadata({
          title: `${title} · Demo`,
          artist: 'June Holiday',
          album: '23',
          artwork: [
            { src: ALBUM_COVER_ART, sizes: '96x96',  type: 'image/png' },
            { src: ALBUM_COVER_ART, sizes: '128x128', type: 'image/png' },
            { src: ALBUM_COVER_ART, sizes: '192x192', type: 'image/png' },
            { src: ALBUM_COVER_ART, sizes: '256x256', type: 'image/png' },
            { src: ALBUM_COVER_ART, sizes: '300x300', type: 'image/png' },
            { src: ALBUM_COVER_ART, sizes: '384x384', type: 'image/png' },
            { src: ALBUM_COVER_ART, sizes: '512x512', type: 'image/png' },
          ],
        });
        try {
          if (isFinite(audio.duration) && audio.duration > 0) {
            navigator.mediaSession.setPositionState({
              duration: audio.duration,
              playbackRate: audio.playbackRate,
              position: audio.currentTime,
            });
          }
        } catch (_) {}
      }
      if (audio.readyState >= 3) {
        audio.play().then(() => { setPlaying(true); startTick(); }).catch(() => {
          setMediaSessionDelegate(null);
          if ('mediaSession' in navigator) navigator.mediaSession.playbackState = 'paused';
        });
      } else {
        setBuffering(true);
        audio.play().then(() => { setPlaying(true); setBuffering(false); startTick(); }).catch(() => {
          setBuffering(false);
          setMediaSessionDelegate(null);
          if ('mediaSession' in navigator) navigator.mediaSession.playbackState = 'paused';
        });
      }
    }
  };

  return (
    <div className={`flex items-center gap-3 mt-3 px-1 py-2 rounded-xl ${isDark ? 'bg-zinc-800/60' : 'bg-zinc-100'}`}>
      <audio ref={audioRef} src={src} preload="auto" />
      <button
        onClick={togglePlay}
        className={`w-7 h-7 rounded-full flex items-center justify-center flex-shrink-0 transition-colors
          ${isDark ? 'bg-purple-500/30 hover:bg-purple-500/50 text-purple-300' : 'bg-purple-100 hover:bg-purple-200 text-purple-600'}`}
      >
        {buffering ? (
          <span className="w-3 h-3 rounded-full border-2 border-current border-t-transparent animate-spin block" />
        ) : playing ? (
          <Pause className="w-3 h-3" />
        ) : (
          <Play className="w-3 h-3 ml-0.5" />
        )}
      </button>
      <div className="flex-1 flex flex-col gap-1">
        <div
          className={`h-1 rounded-full cursor-pointer select-none touch-none ${isDark ? 'bg-zinc-700' : 'bg-zinc-200'}`}
          onClick={(e) => {
            const rect = e.currentTarget.getBoundingClientRect();
            const ratio = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
            const audio = audioRef.current;
            if (audio?.duration) {
              audio.currentTime = ratio * audio.duration;
              if (progressRef.current) progressRef.current.style.width = `${ratio * 100}%`;
            }
          }}
          onMouseDown={(e) => {
            e.preventDefault();
            const bar = e.currentTarget;
            const seek = (clientX: number) => {
              const rect = bar.getBoundingClientRect();
              const ratio = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
              const audio = audioRef.current;
              if (audio?.duration) {
                audio.currentTime = ratio * audio.duration;
                if (progressRef.current) progressRef.current.style.width = `${ratio * 100}%`;
              }
            };
            seek(e.clientX);
            const onMove = (mv: MouseEvent) => seek(mv.clientX);
            const onUp = () => { window.removeEventListener('mousemove', onMove); window.removeEventListener('mouseup', onUp); };
            window.addEventListener('mousemove', onMove);
            window.addEventListener('mouseup', onUp);
          }}
          onTouchStart={(e) => {
            e.preventDefault();
            const bar = e.currentTarget;
            const seek = (clientX: number) => {
              const rect = bar.getBoundingClientRect();
              const ratio = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
              const audio = audioRef.current;
              if (audio?.duration) {
                audio.currentTime = ratio * audio.duration;
                if (progressRef.current) progressRef.current.style.width = `${ratio * 100}%`;
              }
            };
            seek(e.touches[0].clientX);
            const onMove = (mv: TouchEvent) => { mv.preventDefault(); seek(mv.touches[0].clientX); };
            const onEnd = () => { window.removeEventListener('touchmove', onMove); window.removeEventListener('touchend', onEnd); };
            window.addEventListener('touchmove', onMove, { passive: false });
            window.addEventListener('touchend', onEnd);
          }}
        >
          <div ref={progressRef} className="h-full rounded-full bg-purple-500" style={{ width: '0%' }} />
        </div>
      </div>
      <span ref={timeRef} className={`text-[10px] tabular-nums flex-shrink-0 ${isDark ? 'text-zinc-500' : 'text-zinc-400'}`}>
        0:00 / 0:00
      </span>
    </div>
  );
}

function TrackCard({ track, isDark, idx }: { track: Track; isDark: boolean; idx: number }) {
  const [open, setOpen] = useState(false);
  const trackRef = useRef<HTMLDivElement>(null);
  const cfg = statusConfig[track.status];

  useEffect(() => {
    if (open && trackRef.current) {
      // Wait for the Collapse animation (240ms) before scrolling, otherwise the position is computed pre-expand
      setTimeout(() => {
        trackRef.current?.scrollIntoView({
          behavior: 'smooth',
          block: 'center',  // centered
        });
      }, 280);
    }
  }, [open]);

  return (
    <Card delay={80 + idx * 60}>
      <div ref={trackRef}>
        <div
        className="flex items-center gap-4 cursor-pointer select-none"
        onClick={() => (track.story || track.notes || track.demo || track.lyrics) && setOpen(!open)}
      >
        <div className="flex flex-col items-center gap-1 flex-shrink-0 w-8">
          <span className={`text-2xl font-black tabular-nums w-full text-right ${isDark ? 'text-zinc-600' : 'text-zinc-300'}`}>
            {track.number}
          </span>
          <div className={`w-full h-1 rounded-full ${cfg.dot} opacity-60`} />
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 flex-wrap">
            <span className={`font-semibold text-sm ${isDark ? 'text-white' : 'text-zinc-900'}`}>{track.title}</span>
            <span className={`text-[10px] px-2 py-0.5 rounded-full font-medium ${cfg.color}`}>{cfg.label}</span>
            {track.currentlyWorking && (
              <span className="flex items-center gap-1 text-[10px] px-2 py-0.5 rounded-full font-medium bg-purple-500/20 text-purple-300">
                <span className="w-1.5 h-1.5 rounded-full bg-purple-400 animate-pulse-dot inline-block" />
                Working
              </span>
            )}
            {track.tags?.map((t, i) => (
              <span key={i} className={`text-[10px] px-1.5 py-0.5 rounded ${isDark ? 'bg-zinc-800 text-zinc-400' : 'bg-zinc-100 text-zinc-600'}`}>{t}</span>
            ))}
          </div>
        </div>
        {(track.story || track.notes || track.demo || track.lyrics) && (
          <button className={`flex-shrink-0 ${isDark ? 'text-zinc-600 hover:text-zinc-400' : 'text-zinc-300 hover:text-zinc-500'} transition-colors`}>
            {open ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
          </button>
        )}
      </div>

      <Collapse open={open}>
        <div className={`mt-4 pt-4 border-t space-y-3 ${isDark ? 'border-zinc-800' : 'border-zinc-100'}`}>
          {track.demo && (
            <div>
              <p className={`text-xs font-semibold mb-1.5 flex items-center gap-1.5 ${isDark ? 'text-zinc-500' : 'text-zinc-400'}`}>
                <Mic2 className="w-3.5 h-3.5" /> Demo
              </p>
              <DemoPlayer src={track.demo} isDark={isDark} title={track.title} />
            </div>
          )}
          {track.lyrics && (
            <div>
              <p className={`text-xs font-semibold mb-2 flex items-center gap-1.5 ${isDark ? 'text-zinc-500' : 'text-zinc-400'}`}>
                <Music2 className="w-3.5 h-3.5" /> Lyrics
              </p>
              <div className={`text-sm leading-loose italic border-l-2 pl-3 whitespace-pre-line ${isDark ? 'text-zinc-400 border-zinc-700' : 'text-zinc-600 border-zinc-200'}`}>
                {track.lyrics}
              </div>
            </div>
          )}
          {track.story && (
            <div>
              <p className={`text-xs font-semibold mb-1.5 flex items-center gap-1.5 ${isDark ? 'text-zinc-500' : 'text-zinc-400'}`}>
                <FileText className="w-3.5 h-3.5" /> Story
              </p>
              <p className={`text-sm leading-relaxed ${isDark ? 'text-zinc-300' : 'text-zinc-700'}`}>{track.story}</p>
            </div>
          )}
          {track.notes && (
            <div>
              <p className={`text-xs font-semibold mb-1.5 flex items-center gap-1.5 ${isDark ? 'text-zinc-500' : 'text-zinc-400'}`}>
                <Mic2 className="w-3.5 h-3.5" /> Production notes
              </p>
              <p className={`text-sm leading-relaxed ${isDark ? 'text-zinc-400' : 'text-zinc-600'}`}>{track.notes}</p>
            </div>
          )}
        </div>
      </Collapse>
      </div>
    </Card>
  );
}

export function AlbumTab({ isDark, albumData }: { isDark: boolean; albumData: AlbumData }) {
  const { album, tracks } = mapAlbumDataToView(albumData);
  const doneCount = tracks.filter(t => t.status === 'Done').length;
  const [vinylPlaying, setVinylPlaying] = useState(false);
  const [vinylHover, setVinylHover] = useState(false);
  const vinylSpinning = vinylPlaying || vinylHover;

  return (
    <div className="max-w-2xl mx-auto space-y-5">

      {/* ── Hero ── */}
      <Card delay={0}>
        <div className="flex gap-5 items-start">
          {/* Album cover placeholder - spinning vinyl */}
          <div
            className={`w-24 h-24 md:w-28 md:h-28 rounded-2xl flex-shrink-0 bg-gradient-to-br ${album.coverColor} flex items-center justify-center cursor-pointer select-none`}
            onMouseEnter={() => setVinylHover(true)}
            onMouseLeave={() => setVinylHover(false)}
            onClick={() => setVinylPlaying(p => !p)}
            title={vinylPlaying ? 'Click to pause' : 'Click to play'}
          >
            <Disc3 className={`w-10 h-10 ${isDark ? 'text-amber-400/60' : 'text-amber-600/60'} ${
              vinylSpinning ? 'animate-spin-slow' : ''
            }`} />
          </div>
          <div className="flex-1 min-w-0 pt-1">
            <div className="flex items-center gap-2 flex-wrap mb-1">
              <span className={`text-4xl font-black tracking-tighter ${isDark ? 'text-white' : 'text-zinc-900'}`}>{album.title}</span>
              <span className={`text-xs px-2.5 py-1 rounded-full font-medium ${album.statusColor}`}>{album.status}</span>
            </div>
            <p className={`text-sm ${isDark ? 'text-zinc-400' : 'text-zinc-500'}`}>{album.artist} · {album.year}</p>
            {tracks.length > 0 && (
              <div className="flex items-center gap-3 mt-3">
                <div className={`text-xs ${isDark ? 'text-zinc-500' : 'text-zinc-400'}`}>
                  {tracks.length} tracks · {doneCount} done
                </div>
                <div className={`flex-1 h-1.5 rounded-full ${isDark ? 'bg-zinc-800' : 'bg-zinc-200'}`}>
                  <div
                    className="h-full rounded-full bg-gradient-to-r from-amber-500 to-orange-500 transition-all duration-700"
                    style={{ width: tracks.length > 0 ? `${(doneCount / tracks.length) * 100}%` : '0%' }}
                  />
                </div>
              </div>
            )}
          </div>
        </div>
      </Card>

      {/* ── Album concept ── */}
      {album.concept && (
        <Card delay={100}>
          <h3 className={`text-xs font-semibold mb-3 flex items-center gap-2 ${isDark ? 'text-zinc-500' : 'text-zinc-400'} uppercase tracking-wider`}>
            <Lightbulb className="w-3.5 h-3.5 text-amber-400" /> Concept
          </h3>
          <p className={`text-sm leading-relaxed ${isDark ? 'text-zinc-300' : 'text-zinc-700'}`}>{album.concept}</p>
        </Card>
      )}

      {/* ── Tracks ── */}
      <div>
        <h3 className={`text-xs font-semibold mb-3 flex items-center gap-2 px-1 ${isDark ? 'text-zinc-500' : 'text-zinc-400'} uppercase tracking-wider`}>
          <Disc3 className="w-3.5 h-3.5" /> Tracks
        </h3>

        {tracks.length > 0 ? (
          <div className="space-y-2">
            {tracks.map((track, i) => (
              <TrackCard key={i} track={track} isDark={isDark} idx={i} />
            ))}
          </div>
        ) : (
          <Card delay={100}>
            <p className={`text-sm text-center py-4 ${isDark ? 'text-zinc-600' : 'text-zinc-400'}`}>Tracks coming soon…</p>
          </Card>
        )}
      </div>

      {/* ── Timeline ── */}
      {timeline.length > 0 && (
        <div>
          <h3 className={`text-xs font-semibold mb-3 flex items-center gap-2 px-1 ${isDark ? 'text-zinc-500' : 'text-zinc-400'} uppercase tracking-wider`}>
            <Clock className="w-3.5 h-3.5" /> Timeline
          </h3>
          <Card delay={120}>
            <div className="relative">
              <div className={`absolute left-[7px] top-2 bottom-2 w-px ${isDark ? 'bg-zinc-800' : 'bg-zinc-200'}`} />
              <div className="space-y-5">
                {timeline.map((item, i) => (
                  <div key={i} className="flex items-start gap-4 relative">
                    <div className={`w-3.5 h-3.5 rounded-full flex-shrink-0 mt-0.5 z-10 flex items-center justify-center ${
                      item.done
                        ? 'bg-amber-500 border-2 border-amber-500'
                        : isDark ? 'bg-zinc-950 border-2 border-zinc-700' : 'bg-white border-2 border-zinc-300'
                    }`} />
                    <div>
                      <p className={`text-[11px] font-medium ${isDark ? 'text-zinc-500' : 'text-zinc-400'}`}>{item.date}</p>
                      <p className={`text-sm font-semibold ${isDark ? item.done ? 'text-white' : 'text-zinc-400' : item.done ? 'text-zinc-900' : 'text-zinc-500'}`}>{item.event}</p>
                      {item.detail && <p className={`text-xs mt-0.5 ${isDark ? 'text-zinc-500' : 'text-zinc-500'}`}>{item.detail}</p>}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </Card>
        </div>
      )}

      {/* ── Production log ── */}
      {log.length > 0 && (
        <div>
          <h3 className={`text-xs font-semibold mb-3 flex items-center gap-2 px-1 ${isDark ? 'text-zinc-500' : 'text-zinc-400'} uppercase tracking-wider`}>
            <FileText className="w-3.5 h-3.5" /> Production log
          </h3>
          <div className="space-y-2">
            {log.map((entry, i) => (
              <Card key={i} delay={80 + i * 40}>
                <p className={`text-[11px] font-medium mb-1.5 ${isDark ? 'text-zinc-500' : 'text-zinc-400'}`}>{entry.date}</p>
                <p className={`text-sm leading-relaxed ${isDark ? 'text-zinc-300' : 'text-zinc-700'}`}>{entry.content}</p>
              </Card>
            ))}
          </div>
        </div>
      )}

    </div>
  );
}
